import math

def evaluate_expression(n):
    if 2 * n - 1 == 0:
        return None # Should not happen for integer n >= 0

    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
        denominator = 2 * n - 1

        # Check for integer result
        if numerator % denominator == 0:
            return numerator // denominator
        else:
            return float('inf') # Sentinel for non-integer
    except OverflowError:
        return None # Too large to compute

print("n | E(n) | Is Integer?")
print("-" * 25)
integer_values = []
for n in range(16):
    result = evaluate_expression(n)

    if result is not None and result != float('inf'):
        print(f"{n:2} | {result} | Yes")
        integer_values.append(n)
    else:
        print(f"{n:2} | Not Integer | No")

print("\nInteger values found:", integer_values)

