import math

def calculate_E(n):
    """Calculates E(n) = 3 * ((n+2)! + 1) / (2n - 1)"""
    if 2 * n - 1 == 0:
        return None # Should not happen for non-negative n

    # Handle n=0 case separately for presentation, though calculation works
    if n == 0:
        return 3 * ((0+2)! + 1) / (2*0 - 1)

    try:
        numerator = 3 * (math.factorial(n + 2) + 1)
        denominator = 2 * n - 1

        if numerator % denominator == 0:
            return numerator // denominator
        else:
            return None # Not an integer
    except OverflowError:
        # Should not happen with Python's arbitrary precision integers, but good practice
        return None

solutions = []
for n in range(16, 31):
    E_n = calculate_E(n)
    if E_n is not None:
        solutions.append(n)
        # Print the solution and the value for context
        print(f"n={n}: E(n) = {E_n}")

print(f"\nSolutions found in range [16, 30]: {solutions}")

